def home_feed(session_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        try: return dt.astimezone(datetime.timezone.utc).isoformat()
        except Exception: return None

    def _gen_id(prefix):
        return f"{prefix}{int(time.time()*1000)}_{os.urandom(6).hex()}"

    def _log_call(tool_name, session_id_for_log, status, input_obj=None, duration_ms=None,
                  upstream_method=None, upstream_url=None, upstream_status_code=None,
                  error_code=None, error_message=None, response_summary=None):
        calls = _load("api_calls.json")
        ts = _now()
        rid = _gen_id("xhs_call_")
        row = {
            "id": rid,
            "session_id": session_id_for_log,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "upstream_method": upstream_method,
            "upstream_url": upstream_url,
            "upstream_status_code": upstream_status_code,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        }
        calls.append(row)
        _save("api_calls.json", calls)
        return rid

    def _update_call(call_id, **patch):
        calls = _load("api_calls.json")
        for c in calls:
            if c.get("id") == call_id:
                c.update({k: v for k, v in patch.items()})
                c["updated_at"] = _iso(_now())
                _save("api_calls.json", calls)
                return True
        return False

    # Validate input
    if not isinstance(session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]{18,}$", session_id or ""):
        _log_call("home_feed", None, "failed", input_obj={"session_id": session_id}, error_code="VALIDATION_ERROR",
                  error_message="session_id is missing or invalid format", response_summary={"ok": False})
        return _err("VALIDATION_ERROR", "session_id is missing or invalid format")

    sessions = _load("sessions.json")
    sess = next((s for s in sessions if s.get("id") == session_id), None)
    if not sess:
        _log_call("home_feed", session_id, "failed", input_obj={"session_id": session_id},
                  error_code="NOT_FOUND", error_message="session not found", response_summary={"ok": False})
        return _err("NOT_FOUND", "session_id does not exist")

    # Block if no active session exists (global rule)
    if not any(s.get("status") == "active" for s in sessions):
        _log_call("home_feed", session_id, "failed", input_obj={"session_id": session_id},
                  error_code="NO_ACTIVE_SESSION", error_message="no active session available",
                  response_summary={"ok": False})
        return _err("UNAUTHORIZED", "no active session available", error_code="NO_ACTIVE_SESSION")

    if sess.get("status") != "active":
        _log_call("home_feed", session_id, "failed", input_obj={"session_id": session_id},
                  error_code="UNAUTHORIZED", error_message="stored cookie is expired/invalid",
                  response_summary={"ok": False, "session_status": sess.get("status")})
        return _err("UNAUTHORIZED", "stored cookie is expired/invalid")

    # Throttling rule (simple, observable): too many running or too many recent failures
    calls = _load("api_calls.json")
    now = _now()
    recent = []
    for c in calls:
        created = c.get("created_at")
        if isinstance(created, str):
            try:
                s = created[:-1] + "+00:00" if created.endswith("Z") else created
                dt = datetime.datetime.fromisoformat(s)
            except Exception:
                continue
        else:
            continue
        if (now - dt).total_seconds() <= 60:
            recent.append(c)
    running_count = sum(1 for c in calls if c.get("status") == "running")
    recent_failures = sum(1 for c in recent if c.get("status") == "failed")
    if running_count >= 5 or recent_failures >= 10:
        call_id = _log_call("home_feed", session_id, "throttled", input_obj={"session_id": session_id},
                            error_code="RATE_LIMIT", error_message="throttled",
                            response_summary={"ok": False, "running": running_count, "recent_failures_60s": recent_failures})
        return _err("RATE_LIMIT", "throttled", api_call_id=call_id)

    call_id = _log_call("home_feed", session_id, "received", input_obj={"session_id": session_id})
    t0 = time.time()
    if not _update_call(call_id, status="running"):
        return _err("CONFLICT", "failed to transition api_call to running")

    # Offline implementation: no upstream access; still mutate notes if any are already discovered in store
    # and attribute that they were "collected_from" home_feed if not set.
    notes = _load("notes.json")
    ts = _now()
    mutated = 0
    for n in notes:
        if n.get("collected_from") is None:
            n["collected_from"] = "home_feed"
            n["updated_at"] = _iso(ts)
            mutated += 1
        if n.get("status") in (None, ""):
            n["status"] = "discovered"
            n["updated_at"] = _iso(ts)
            mutated += 1
    if mutated:
        _save("notes.json", notes)

    # Mark session last_ok_at as best-effort "upstream ok" since call succeeded locally
    sess["last_ok_at"] = _iso(ts)
    sess["updated_at"] = _iso(ts)
    _save("sessions.json", sessions)

    payload = {"items": [], "note_ids": [], "source": "offline_store"}
    _update_call(
        call_id,
        status="succeeded",
        duration_ms=int((time.time() - t0) * 1000),
        upstream_method="GET",
        upstream_url="https://xhs.example.local/home_feed",
        upstream_status_code=200,
        response_summary={"ok": True, "items": 0, "notes_touched": mutated, "source": "offline_store"},
    )
    return {"api_call_id": call_id, "feed": payload}

def get_note_content(session_id, url, **_extra):
    import json, os, datetime, re, time, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        try:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}{uuid.uuid4().hex[:8]}"

    def _log_api_call(tool_name, sess_id, status, input_obj=None, upstream_method=None, upstream_url=None,
                      upstream_status_code=None, duration_ms=None, error_code=None, error_message=None,
                      response_summary=None):
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            calls = []
        ts = _iso(_utcnow())
        row = {
            "id": _new_id("xhs_call"),
            "session_id": sess_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "upstream_method": upstream_method,
            "upstream_url": upstream_url,
            "upstream_status_code": upstream_status_code,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": ts,
            "updated_at": ts,
        }
        calls.append(row)
        _save("api_calls.json", calls)
        return row

    def _update_api_call(call_id, new_status=None, **patch):
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            return False
        transitions = {
            "received": {"running", "throttled", "failed"},
            "running": {"succeeded", "failed", "throttled"},
            "throttled": {"running", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        for c in calls:
            if isinstance(c, dict) and c.get("id") == call_id:
                if new_status is not None:
                    cur = c.get("status")
                    if cur not in transitions or new_status not in transitions[cur]:
                        return False
                    c["status"] = new_status
                for k, v in patch.items():
                    c[k] = v
                c["updated_at"] = _iso(_utcnow())
                _save("api_calls.json", calls)
                return True
        return False

    def _rate_limited():
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            return False, None
        now = _utcnow()
        running = sum(1 for c in calls if isinstance(c, dict) and c.get("status") == "running")
        if running >= 5:
            return True, "TOO_MANY_RUNNING"
        recent_window = now - datetime.timedelta(seconds=60)
        recent_fail = 0
        for c in calls:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "failed":
                continue
            dt = _parse_dt(c.get("created_at"))
            if dt and dt >= recent_window:
                recent_fail += 1
        if recent_fail >= 10:
            return True, "TOO_MANY_RECENT_FAILURES"
        return False, None

    def _canonicalize_and_extract(u):
        try:
            p = urllib.parse.urlsplit(u)
        except Exception:
            return None, None, None, None
        qs = urllib.parse.parse_qs(p.query, keep_blank_values=True)
        xsec = None
        for k in ("xsec_token", "xsec", "xsecToken"):
            if k in qs and qs[k]:
                xsec = qs[k][0]
                break
        # canonical_url drops transient query params (including xsec_token)
        kept = {}
        for k, v in qs.items():
            if k in ("xsec_token", "xsec", "xsecToken"):
                continue
            if not v:
                continue
            kept[k] = v
        canonical_q = urllib.parse.urlencode(kept, doseq=True)
        canonical = urllib.parse.urlunsplit((p.scheme, p.netloc, p.path, canonical_q, ""))
        url_with_xsec = u
        # try derive xhs_note_id from path segments (best effort)
        xhs_note_id = None
        m = re.search(r"/explore/([A-Za-z0-9]+)", p.path)
        if not m:
            m = re.search(r"/discovery/item/([A-Za-z0-9]+)", p.path)
        if not m:
            m = re.search(r"(?:note|item)[=/]([A-Za-z0-9]+)", u)
        if m:
            xhs_note_id = m.group(1)
        return canonical, url_with_xsec, xsec, xhs_note_id

    t0 = time.time()

    # Validate inputs per tool schema
    if not isinstance(session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id.", field="session_id")
    if not isinstance(url, str) or len(url) < 1:
        return _err("VALIDATION_ERROR", "Invalid url.", field="url")

    canonical_url, url_with_xsec, xsec_token, xhs_note_id = _canonicalize_and_extract(url)
    # Relax validation: accept any non-empty url even if xsec missing (audit requirement); record it as unavailable to fetch.
    missing_xsec = not (isinstance(xsec_token, str) and xsec_token.strip())

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Session must exist; do not reject because its status is not active (caller can pass any stored session)
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        # still log call attempt
        call = _log_api_call(
            "get_note_content", session_id, "failed",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="SESSION_NOT_FOUND",
            error_message="session_id does not exist",
            response_summary=None,
        )
        return _err("NOT_FOUND", "Session not found.", session_id=session_id, api_call_id=call.get("id"))

    # If no active session exists anywhere, block (business rule)
    any_active = any(isinstance(s, dict) and s.get("status") == "active" for s in sessions)
    # But allow if THIS call carries an active session_id? rule says blocked if no sessions row active; so check global.
    if not any_active:
        call = _log_api_call(
            "get_note_content", session_id, "failed",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="NO_ACTIVE_SESSION",
            error_message="no active session; blocked before upstream call",
            response_summary=None,
        )
        return _err("UNAUTHORIZED", "No active session; blocked before upstream call.", api_call_id=call.get("id"), session_id=session_id)

    throttled, throttle_reason = _rate_limited()
    if throttled:
        call = _log_api_call(
            "get_note_content", session_id, "throttled",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="RATE_LIMITED",
            error_message="too many recent calls; throttled locally",
            response_summary={"reason": throttle_reason},
        )
        return _err("RATE_LIMIT", "Rate limited.", api_call_id=call.get("id"), reason=throttle_reason)

    # Create api_call received -> running
    call = _log_api_call("get_note_content", session_id, "received", input_obj={"url": url}, upstream_method="GET", upstream_url=canonical_url)
    if not _update_api_call(call.get("id"), new_status="running"):
        # should not happen, but return error object rather than raise
        return _err("CONFLICT", "Call lifecycle conflict.", api_call_id=call.get("id"))

    # Upsert note record (best effort, even if we cannot fetch content)
    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    note_row = None
    if xhs_note_id:
        for n in notes:
            if isinstance(n, dict) and n.get("xhs_note_id") == xhs_note_id:
                note_row = n
                break
    if note_row is None:
        # create new note
        now_iso = _iso(_utcnow())
        note_row = {
            "id": _new_id("xhs_note"),
            "xhs_note_id": xhs_note_id or _new_id("xhs_xid"),  # fallback to satisfy non-null; local placeholder
            "status": "discovered",
            "canonical_url": canonical_url,
            "url_with_xsec_token": url_with_xsec,
            "xsec_token": xsec_token if not missing_xsec else None,
            "title": None,
            "body_text": None,
            "author_xhs_id": None,
            "author_name": None,
            "cover_image_url": None,
            "media_urls": None,
            "like_count": None,
            "comment_count": None,
            "collected_from": "get_note_content",
            "last_content_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        notes.append(note_row)
    else:
        # update URLs and token; keep status at least discovered
        note_row["canonical_url"] = canonical_url or note_row.get("canonical_url")
        note_row["url_with_xsec_token"] = url_with_xsec or note_row.get("url_with_xsec_token")
        if not missing_xsec:
            note_row["xsec_token"] = xsec_token
        if note_row.get("status") not in ("discovered", "content_fetched", "unavailable", "deleted"):
            note_row["status"] = "discovered"
        if note_row.get("status") == "deleted":
            # cannot transition out of deleted
            pass
        note_row["updated_at"] = _iso(_utcnow())

    _save("notes.json", notes)

    # Simulated upstream behavior (offline): if xsec missing, treat as failed validation to upstream
    if missing_xsec:
        _update_api_call(
            call.get("id"),
            new_status="failed",
            duration_ms=int((time.time() - t0) * 1000),
            upstream_status_code=400,
            error_code="XHS_XSEC_MISSING",
            error_message="url missing xsec_token; cannot fetch upstream",
            response_summary={"note_internal_id": note_row.get("id"), "source": "local"},
        )
        return {
            "note_id": note_row.get("id"),
            "note": note_row,
            "upstream": None,
            "meta": {
                "api_call_id": call.get("id"),
                "duration_ms": int((time.time() - t0) * 1000),
                "source": "local",
            },
        }

    # "Successful" offline fetch: mark content_fetched and set fetch time; do not fabricate huge payload
    now = _utcnow()
    # lifecycle transitions: discovered/unavailable -> content_fetched allowed; deleted -> not allowed
    if note_row.get("status") == "deleted":
        _update_api_call(
            call.get("id"),
            new_status="failed",
            duration_ms=int((time.time() - t0) * 1000),
            upstream_status_code=404,
            error_code="NOTE_DELETED",
            error_message="note is deleted locally; upstream fetch skipped",
            response_summary={"note_internal_id": note_row.get("id")},
        )
        return _err("NOT_FOUND", "Note deleted.", api_call_id=call.get("id"), note_id=note_row.get("id"))

    note_row["status"] = "content_fetched"
    note_row["last_content_fetched_at"] = _iso(now)
    note_row["updated_at"] = _iso(now)
    _save("notes.json", notes)

    upstream_payload = {
        "note_id": note_row.get("xhs_note_id"),
        "xsec_token": note_row.get("xsec_token"),
        "canonical_url": note_row.get("canonical_url"),
        "fetched_at": _iso(now),
    }

    _update_api_call(
        call.get("id"),
        new_status="succeeded",
        duration_ms=int((time.time() - t0) * 1000),
        upstream_status_code=200,
        response_summary={"note_internal_id": note_row.get("id"), "source": "offline_stub"},
    )

    return {
        "note_id": note_row.get("id"),
        "note": note_row,
        "upstream": upstream_payload,
        "meta": {
            "api_call_id": call.get("id"),
            "duration_ms": int((time.time() - t0) * 1000),
            "source": "offline_stub",
        },
    }

