        for k in ("xsec_token", "xsec", "xsecToken"):
            if k in qs and qs[k]:
                xsec = qs[k][0]
                break
        # canonical_url drops transient query params (including xsec_token)
        kept = {}
        for k, v in qs.items():
            if k in ("xsec_token", "xsec", "xsecToken"):
                continue
            if not v:
                continue
            kept[k] = v
        canonical_q = urllib.parse.urlencode(kept, doseq=True)
        canonical = urllib.parse.urlunsplit((p.scheme, p.netloc, p.path, canonical_q, ""))
        url_with_xsec = u
        xhs_note_id = None
        m = re.search(r"/explore/([A-Za-z0-9]+)", p.path)
        if not m:
            m = re.search(r"/discovery/item/([A-Za-z0-9]+)", p.path)
        if not m:
            m = re.search(r"(?:note|item)[=/]([A-Za-z0-9]+)", u)
        if m:
            xhs_note_id = m.group(1)
        return canonical, url_with_xsec, xsec, xhs_note_id

    t0 = time.time()

    if not isinstance(session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id.", field="session_id")
    if not isinstance(url, str) or len(url) < 1:
        return _err("VALIDATION_ERROR", "Invalid url.", field="url")

    canonical_url, url_with_xsec, xsec_token, xhs_note_id = _canonicalize_and_extract(url)
    # Relax strict xsec validation: allow call to proceed and return stored/empty comments if missing.
    missing_xsec = not (isinstance(xsec_token, str) and xsec_token.strip())

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        call = _log_api_call(
            "get_note_comments", session_id, "failed",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="SESSION_NOT_FOUND",
            error_message="session_id does not exist",
        )
        return _err("NOT_FOUND", "Session not found.", session_id=session_id, api_call_id=call.get("id"))

    any_active = any(isinstance(s, dict) and s.get("status") == "active" for s in sessions)
    if not any_active:
        call = _log_api_call(
            "get_note_comments", session_id, "failed",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="NO_ACTIVE_SESSION",
            error_message="no active session; blocked before upstream call",
        )
        return _err("UNAUTHORIZED", "No active session; blocked before upstream call.", api_call_id=call.get("id"), session_id=session_id)

    throttled, throttle_reason = _rate_limited()
    if throttled:
        call = _log_api_call(
            "get_note_comments", session_id, "throttled",
            input_obj={"url": url},
            duration_ms=int((time.time() - t0) * 1000),
            error_code="RATE_LIMITED",
            error_message="too many recent calls; throttled locally",
            response_summary={"reason": throttle_reason},
        )
        return _err("RATE_LIMIT", "Rate limited.", api_call_id=call.get("id"), reason=throttle_reason)

    call = _log_api_call("get_note_comments", session_id, "received", input_obj={"url": url}, upstream_method="GET", upstream_url=canonical_url)
    if not _update_api_call(call.get("id"), new_status="running"):
        return _err("CONFLICT", "Call lifecycle conflict.", api_call_id=call.get("id"))

    # Ensure note exists / upsert by xhs_note_id when possible
    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []
    note_row = None
    if xhs_note_id:
        for n in notes:
            if isinstance(n, dict) and n.get("xhs_note_id") == xhs_note_id:
                note_row = n
                break
    if note_row is None:
        now_iso = _iso(_utcnow())
        note_row = {
            "id": _new_id("xhs_note"),
            "xhs_note_id": xhs_note_id or _new_id("xhs_xid"),
            "status": "discovered",
            "canonical_url": canonical_url,
            "url_with_xsec_token": url_with_xsec,
            "xsec_token": xsec_token if not missing_xsec else None,
            "title": None,
            "body_text": None,
            "author_xhs_id": None,
            "author_name": None,
            "cover_image_url": None,
            "media_urls": None,
            "like_count": None,
            "comment_count": None,
            "collected_from": "get_note_comments",
            "last_content_fetched_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        notes.append(note_row)
    else:
        note_row["canonical_url"] = canonical_url or note_row.get("canonical_url")
        note_row["url_with_xsec_token"] = url_with_xsec or note_row.get("url_with_xsec_token")
        if not missing_xsec:
            note_row["xsec_token"] = xsec_token
        note_row["updated_at"] = _iso(_utcnow())
    _save("notes.json", notes)

    # Offline "fetch comments": return existing comments for this note; if none, return empty.
    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    note_internal_id = note_row.get("id")
    existing = [c for c in comments if isinstance(c, dict) and c.get("note_id") == note_internal_id and c.get("status") != "deleted"]

    # If xsec is missing, mark call failed but still return local data (empty or existing)
    if missing_xsec:
        _update_api_call(
            call.get("id"),
            new_status="failed",
            duration_ms=int((time.time() - t0) * 1000),
            upstream_status_code=400,
            error_code="XHS_XSEC_MISSING",
            error_message="url missing xsec_token; cannot fetch upstream",
            response_summary={"note_internal_id": note_internal_id, "returned_count": len(existing), "source": "local"},
        )
        return {
            "note_id": note_internal_id,
            "comments": existing,
            "upstream": None,
            "meta": {
                "api_call_id": call.get("id"),
                "duration_ms": int((time.time() - t0) * 1000),
                "returned_count": len(existing),
                "source": "local",
            },
        }

    # Mark succeeded and stamp fetched_via_call_id for returned ones (mutation must have effect)
    mutated = 0
    now_iso = _iso(_utcnow())
    for c in comments:
        if isinstance(c, dict) and c.get("note_id") == note_internal_id and c.get("status") != "deleted":
            if c.get("fetched_via_call_id") != call.get("id"):
                c["fetched_via_call_id"] = call.get("id")
                c["updated_at"] = now_iso
                mutated += 1
    if mutated:
        _save("comments.json", comments)

    _update_api_call(
        call.get("id"),
        new_status="succeeded",
        duration_ms=int((time.time() - t0) * 1000),
        upstream_status_code=200,
        response_summary={"note_internal_id": note_internal_id, "returned_count": len(existing), "source": "offline_stub"},
    )

    return {
        "note_id": note_internal_id,
        "comments": existing,
        "upstream": {"note_id": note_row.get("xhs_note_id"), "fetched_at": now_iso, "returned_count": len(existing)},
        "meta": {
            "api_call_id": call.get("id"),
            "duration_ms": int((time.time() - t0) * 1000),
            "returned_count": len(existing),
            "source": "offline_stub",
        },
    }

def create_session(cookie_raw, user_identifier=None, validate_immediately=None, **_extra):
    import json, os, datetime, uuid, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        try:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}{uuid.uuid4().hex[:8]}"

    def _fingerprint_cookie(raw):
        return "sha256:" + hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _log_api_call(sess_id, status, input_obj=None, upstream_method=None, upstream_url=None,
                      upstream_status_code=None, duration_ms=None, error_code=None, error_message=None,
                      response_summary=None):
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            calls = []
        ts = _iso(_utcnow())
        row = {
            "id": _new_id("xhs_call"),
            "session_id": sess_id,
            "tool_name": "check_cookie",
            "status": status,
            "input": input_obj,
            "upstream_method": upstream_method,
            "upstream_url": upstream_url,
            "upstream_status_code": upstream_status_code,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": ts,
            "updated_at": ts,
        }
        calls.append(row)
        _save("api_calls.json", calls)
        return row

    # Defaults
    if validate_immediately is None:
        validate_immediately = True

    # Validate inputs
    if not isinstance(cookie_raw, str) or not cookie_raw.strip():
        return _err("VALIDATION_ERROR", "cookie_raw is required.", field="cookie_raw")
    if user_identifier is not None:
        if not isinstance(user_identifier, str) or not user_identifier.strip():
            return _err("VALIDATION_ERROR", "user_identifier must be a non-empty string when provided.", field="user_identifier")
    if validate_immediately is not None and not isinstance(validate_immediately, bool):
        return _err("VALIDATION_ERROR", "validate_immediately must be boolean.", field="validate_immediately")

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    fp = _fingerprint_cookie(cookie_raw.strip())

    # CONFLICT: non-disabled session with same cookie_fingerprint already exists
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("cookie_fingerprint") == fp and s.get("status") != "disabled":
            return _err("CONFLICT", "A non-disabled session with the same cookie_fingerprint already exists.", session_id=s.get("id"))

    # Enforce: expires_at >= created_at when expires_at not null (we set expires_at null unless derived)
    now = _utcnow()
    now_iso = _iso(now)

    # Enforce: at most one active session at a time (unique where status='active')
    # For newly created row, default to 'active' if no active exists; otherwise 'rotating' unless validate says otherwise.
    has_active = any(isinstance(s, dict) and s.get("status") == "active" for s in sessions)
    initial_status = "rotating" if has_active else "active"

    new_row = {
        "id": _new_id("xhs_sess"),
        "status": initial_status,
        "cookie_raw": cookie_raw.strip(),
        "cookie_fingerprint": fp,
        "user_identifier": user_identifier.strip() if isinstance(user_identifier, str) and user_identifier.strip() else None,
        "last_checked_at": None,
        "last_ok_at": None,
        "last_error_code": None,
        "last_error_message": None,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    sessions.append(new_row)
    _save("sessions.json", sessions)

    # Optional immediate validation: offline behavior cannot really validate; interpret as "format accepted"
    # Must NOT refuse as UNAUTHORIZED by comparing cookie to non-existent plaintext; accept and mark checked.
    if validate_immediately:
        # update last_checked_at every run; set status to active on "success"
        # if already another active exists, we cannot set active without violating uniqueness; keep rotating.
        new_row["last_checked_at"] = now_iso
        if not has_active:
            new_row["status"] = "active"
            new_row["last_ok_at"] = now_iso
            new_row["last_error_code"] = None
            new_row["last_error_message"] = None
        else:
            new_row["status"] = "rotating"
            new_row["last_ok_at"] = None
            new_row["last_error_code"] = "ACTIVE_SESSION_EXISTS"
            new_row["last_error_message"] = "another active session exists; created session in rotating state"
        new_row["updated_at"] = _iso(_utcnow())
        _save("sessions.json", sessions)

        # Log as check_cookie call (received->running->succeeded simplified)
        t0 = time.time()
        call = _log_api_call(
            new_row.get("id"),
            "succeeded",
            input_obj={"validate_immediately": True},
            upstream_method="GET",
            upstream_url="https://www.xiaohongshu.com/api/session/check",
            upstream_status_code=200,
            duration_ms=int((time.time() - t0) * 1000),
            response_summary={"validated": True, "result": "offline_stub"},
        )
        return {"session": new_row, "meta": {"api_call_id": call.get("id")}}

    # validate_immediately False: still return created row, no upstream call log required by rules.
    return {"session": new_row, "meta": {"validated": False}}

def list_sessions(status=None, user_identifier=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        import uuid
        raw = uuid.uuid4().hex + uuid.uuid4().hex[:8]
        return f"{prefix}_{raw}"

    def _log_list_call(api_calls, status_value, error=None, response_summary=None):
        ts = _now()
        row = {
            "id": _new_id("xhs_call"),
            "session_id": None,
            "tool_name": "check_cookie",  # no list tool in schema; best available audit bucket
            "status": "succeeded" if error is None else "failed",
            "input": {"op": "list_sessions", "status": status_value, "user_identifier": user_identifier, "limit": limit, "cursor": cursor, "sort": sort},
            "upstream_method": None,
            "upstream_url": None,
            "upstream_status_code": None,
            "duration_ms": 0,
            "error_code": None if error is None else error.get("code"),
            "error_message": None if error is None else error.get("message"),
            "response_summary": response_summary,
            "created_at": ts,
            "updated_at": ts,
        }
        api_calls.append(row)
        return row

    # Defaults
    if limit is None:
        limit = 50
    if sort is None:
        sort = "created_at_desc"

    # Validate
    allowed_status = {"active", "expired", "invalid", "rotating", "disabled"}
    if status is not None and status not in allowed_status:
        api_calls = _load("api_calls.json")
        call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "Invalid status filter."})
        _save("api_calls.json", api_calls)
        return _err("VALIDATION_ERROR", "Invalid status filter.", api_call_id=call["id"])

    if user_identifier is not None and (not isinstance(user_identifier, str) or not user_identifier.strip()):
        api_calls = _load("api_calls.json")
        call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "Invalid user_identifier filter."})
        _save("api_calls.json", api_calls)
        return _err("VALIDATION_ERROR", "Invalid user_identifier filter.", api_call_id=call["id"])

    if not isinstance(limit, int) or limit < 1 or limit > 200:
        api_calls = _load("api_calls.json")
        call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 200."})
        _save("api_calls.json", api_calls)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", api_call_id=call["id"])

    allowed_sort = {"created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"}
    if sort not in allowed_sort:
        api_calls = _load("api_calls.json")
        call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "Invalid sort value."})
        _save("api_calls.json", api_calls)
        return _err("VALIDATION_ERROR", "Invalid sort value.", api_call_id=call["id"])

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            api_calls = _load("api_calls.json")
            call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor."})
            _save("api_calls.json", api_calls)
            return _err("VALIDATION_ERROR", "Invalid cursor.", api_call_id=call["id"])
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            start = int(decoded.decode("utf-8"))
            if start < 0:
                raise ValueError("neg")
        except Exception:
            api_calls = _load("api_calls.json")
            call = _log_list_call(api_calls, status, error={"code": "VALIDATION_ERROR", "message": "Malformed cursor."})
            _save("api_calls.json", api_calls)
            return _err("VALIDATION_ERROR", "Malformed cursor.", api_call_id=call["id"])

    sessions = _load("sessions.json")

    # Filter
    rows = sessions
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if user_identifier is not None:
        ui = user_identifier.strip()
        rows = [s for s in rows if s.get("user_identifier") == ui]

    # Sort
    def key_dt(v):
        d = _dt_parse(v) or datetime.datetime(1970, 1, 1)
        return d

    reverse = sort.endswith("_desc")
    if sort.startswith("created_at_"):
        rows.sort(key=lambda r: key_dt(r.get("created_at")), reverse=reverse)
    else:
        rows.sort(key=lambda r: key_dt(r.get("updated_at")), reverse=reverse)

    total = len(rows)
    page = rows[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_start).encode("utf-8")).decode("utf-8").rstrip("=")

    # Redact cookie_raw
    out = []
    for s in page:
        r = dict(s)
        r["cookie_raw"] = None
        out.append(r)

    api_calls = _load("api_calls.json")
    call = _log_list_call(api_calls, status, response_summary={"returned": len(out), "total": total, "has_more": has_more})
    _save("api_calls.json", api_calls)

    return {
        "api_call_id": call["id"],
        "sessions": out,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more, "sort": sort},
    }

def update_session(session_id, status=None, cookie_raw=None, user_identifier=None, **_extra):
    import json, os, datetime, hashlib, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(session_id, str) or not re.match(r"^xhs_sess_[A-Za-z0-9]{18,}$", session_id):
        return _err("VALIDATION_ERROR", "Invalid session_id.", field="session_id")

    allowed_status = {"active", "expired", "invalid", "rotating", "disabled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if cookie_raw is not None:
        if not isinstance(cookie_raw, str) or len(cookie_raw) < 1:
            return _err("VALIDATION_ERROR", "cookie_raw must be a non-empty string.", field="cookie_raw")

    if user_identifier is not None:
        if not isinstance(user_identifier, str) or len(user_identifier) < 1:
            return _err("VALIDATION_ERROR", "user_identifier must be a non-empty string.", field="user_identifier")

    sessions = _load("sessions.json")

    idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == session_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Session not found.", session_id=session_id)

    sess = sessions[idx]
    cur_status = sess.get("status")

    # Lifecycle transitions
    transitions = {
        "active": {"expired", "invalid", "rotating", "disabled"},
        "rotating": {"active", "invalid", "disabled"},
        "expired": {"rotating", "disabled"},
        "invalid": {"rotating", "disabled"},
        "disabled": set(),
    }
    if not isinstance(cur_status, str) or cur_status not in transitions:
        # treat as validation error on stored row state
        return _err("VALIDATION_ERROR", "Session has invalid stored status.", session_id=session_id)

    # cookie fingerprint uniqueness
    new_fingerprint = None
    if cookie_raw is not None:
        # Stable hash for dedup/auditing
        new_fingerprint = hashlib.sha256(cookie_raw.encode("utf-8")).hexdigest()
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("id") != session_id and s.get("cookie_fingerprint") is not None and s.get("cookie_fingerprint") == new_fingerprint:
                return _err("CONFLICT", "cookie_fingerprint already exists on another session.", field="cookie_raw")

    # Determine target status considering business rule: cookie replacement may set rotating until validated.
    target_status = cur_status
    if status is not None:
        target_status = status

    if cookie_raw is not None and status is None:
        # "may set status to rotating until validated" — do so if allowed transition
        if "rotating" in transitions.get(cur_status, set()):
            target_status = "rotating"

    # Validate transition if status changes
    if target_status != cur_status:
        if target_status not in transitions.get(cur_status, set()):
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur_status, to_status=target_status)

    # Enforce at most one active session
    if target_status == "active":
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("id") != session_id and s.get("status") == "active":
                return _err("CONFLICT", "Another active session already exists.", existing_active_session_id=s.get("id"))

    # Apply updates
    changed = False
    if cookie_raw is not None:
        sess["cookie_raw"] = cookie_raw
        sess["cookie_fingerprint"] = new_fingerprint
        changed = True

    if user_identifier is not None:
        sess["user_identifier"] = user_identifier
        changed = True

    if target_status != cur_status:
        sess["status"] = target_status
        changed = True

    if not changed:
        # no-op update should be refused: the session exists but nothing to do
        return _err("VALIDATION_ERROR", "No fields to update were provided.")

    sess["updated_at"] = now

    # Constraint: expires_at >= created_at if not null
    def _parse_dt(x):
        if x is None:
            return None
        if not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x2 = x[:-1]
                return datetime.datetime.fromisoformat(x2)
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    if sess.get("expires_at") is not None:
        ca = _parse_dt(sess.get("created_at"))
        ea = _parse_dt(sess.get("expires_at"))
        if ca is None or ea is None:
            return _err("VALIDATION_ERROR", "Invalid datetime format on session for expires_at/created_at.")
        if ea < ca:
            return _err("VALIDATION_ERROR", "expires_at must be >= created_at.", field="expires_at")

    sessions[idx] = sess
    _save("sessions.json", sessions)

    return {
        "session": sess,
        "meta": {
            "updated": True,
            "duration_ms": int((time.time() - started) * 1000),
        },
    }

def list_notes(status=None, xhs_note_id=None, author_xhs_id=None, collected_from=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           	    return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    # Validate filters
    if status is not None:
        if not isinstance(status, str) or status not in {"discovered", "content_fetched", "deleted", "unavailable"}:
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if xhs_note_id is not None:
        if not isinstance(xhs_note_id, str) or len(xhs_note_id) < 1:
            return _err("VALIDATION_ERROR", "Invalid xhs_note_id filter.", field="xhs_note_id")
    if author_xhs_id is not None:
        if not isinstance(author_xhs_id, str) or len(author_xhs_id) < 1:
            return _err("VALIDATION_ERROR", "Invalid author_xhs_id filter.", field="author_xhs_id")
    if collected_from is not None:
        if not isinstance(collected_from, str) or collected_from not in {"home_feed", "search_notes", "get_note_content", "get_note_comments", "unknown"}:
            return _err("VALIDATION_ERROR", "Invalid collected_from filter.", field="collected_from")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer between 1 and 200.", field="limit")

    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    if sort is None:
        sort = "updated_at_desc"
    if not isinstance(sort, str) or sort not in {"created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc", "last_content_fetched_at_desc"}:
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    # Decode cursor
    start_index = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or not isinstance(payload.get("i"), int) or payload.get("i") < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start_index = payload["i"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    # Filter
    def _match(n):
        if not isinstance(n, dict):
            return False
        if status is not None and n.get("status") != status:
            return False
        if xhs_note_id is not None and n.get("xhs_note_id") != xhs_note_id:
            return False
        if author_xhs_id is not None and n.get("author_xhs_id") != author_xhs_id:
            return False
        if collected_from is not None:
            cf = n.get("collected_from")
            # allow unknown filter to match null/unknown
            if collected_from == "unknown":
                if cf not in (None, "", "unknown"):
                    return False
            else:
                if cf != collected_from:
                    return False
        return True

    filtered = [n for n in notes if _match(n)]
    total = len(filtered)

    # Sort
    def _key_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _sort_key(n):
        if sort.startswith("created_at"):
            return _key_dt(n.get("created_at"))
        if sort.startswith("updated_at"):
            return _key_dt(n.get("updated_at"))
        if sort == "last_content_fetched_at_desc":
            return _key_dt(n.get("last_content_fetched_at"))
        return _key_dt(n.get("updated_at"))

    reverse = sort.endswith("_desc") or sort == "last_content_fetched_at_desc"
    # Put None dates at the end consistently
    filtered.sort(key=lambda n: (_sort_key(n) is None, _sort_key(n)), reverse=reverse)

    # Page
    page = filtered[start_index:start_index + limit]
    next_index = start_index + len(page)
    has_more = next_index < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "i": next_index}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "notes": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "duration_ms": int((time.time() - started) * 1000),
        },
    }

def get_note(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0481000" if __import__("os").path.isdir("./environment_mix/0481000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_api_call(tool_name, *, status, session_id=None, input_obj=None, error_code=None, error_message=None, response_summary=None, duration_ms=None):
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            calls = []
        now = _utcnow()
        row = {
            "id": _new_id("xhs_call"),
            "session_id": session_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj,
            "upstream_method": None,
            "upstream_url": None,
            "upstream_status_code": None,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        calls.append(row)
        _save("api_calls.json", calls)
        return row

    def _rate_limit_check():
        calls = _load("api_calls.json")
        if not isinstance(calls, list):
            return None
        now = _utcnow()

        running = 0
        for c in calls:
            if isinstance(c, dict) and c.get("status") == "running":
                running += 1
        if running >= 5:
            return ("RATE_LIMIT", "too many running calls; throttled locally")

        recent_failed = 0
        for c in calls:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "failed":
                continue
            created = _parse_iso(c.get("created_at"))
            if created is None:
                continue
            # last 60 seconds window
            if (now - created).total_seconds() <= 60:
                recent_failed += 1
        if recent_failed >= 8:
            return ("RATE_LIMIT", "too many recent failures; throttled locally")
        return None

    # ---- validation ----
    if not isinstance(id, str) or not id.strip():
        # still log the call attempt
        api_call = _append_api_call(
            "get_note_content",  # api_calls.tool_name enum has no get_note; use closest note read.
            status="failed",
            session_id=None,
            input_obj={"id": id},
            error_code="VALIDATION_ERROR",
            error_message="id must be a non-empty string",
            duration_ms=max(0, int((time.time() - started) * 1000)),
        )
        return _err("VALIDATION_ERROR", "id must be a non-empty string", api_call_id=api_call["id"])

    # ---- throttling ----
    rl = _rate_limit_check()
    if rl is not None:
        code, msg = rl
        api_call = _append_api_call(
            "get_note_content",
            status="throttled",
            session_id=None,
            input_obj={"id": id},
            error_code="RATE_LIMITED",
            error_message=msg,
            duration_ms=max(0, int((time.time() - started) * 1000)),
            response_summary={"source": "throttle"},
        )
        return _err(code, msg, api_call_id=api_call["id"])

    # Resolve an active session if present (do not fail if missing; get_note is local read).
    sessions = _load("sessions.json")
    active_session_id = None
    if isinstance(sessions, list):
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str):
                active_session_id = s["id"]
                break

    # ---- api call lifecycle: received -> running ----
    api_call = _append_api_call(
        "get_note_content",
        status="received",
        session_id=active_session_id,
        input_obj={"id": id},
    )
    # transition to running
    calls = _load("api_calls.json")
    if isinstance(calls, list):
        now = _utcnow()
        for c in calls:
            if isinstance(c, dict) and c.get("id") == api_call["id"]:
                # received -> running is legal
                c["status"] = "running"
                c["updated_at"] = _iso(now)
                break
        _save("api_calls.json", calls)

    # ---- fetch note ----
    notes = _load("notes.json")
    if not isinstance(notes, list):
        notes = []

    note = None
    for n in notes:
        if isinstance(n, dict) and n.get("id") == id:
            note = n
            break

    duration_ms = max(0, int((time.time() - started) * 1000))
    now = _utcnow()

    calls = _load("api_calls.json")
    if not isinstance(calls, list):
        calls = []

    def _finalize(status, *, error_code=None, error_message=None, response_summary=None):
        for c in calls:
            if isinstance(c, dict) and c.get("id") == api_call["id"]:
                cur = c.get("status")
                # running -> succeeded/failed/throttled are legal
                if cur not in ("running", "received", "throttled"):
                    # don't crash; force to failed with internal classification
                    c["status"] = "failed"
                    c["error_code"] = "INVALID_TRANSITION"
                    c["error_message"] = "illegal api_calls status transition"
                else:
                    c["status"] = status
                    c["error_code"] = error_code
                    c["error_message"] = error_message
                    c["response_summary"] = response_summary
                c["duration_ms"] = duration_ms
                c["updated_at"] = _iso(now)
                break
        _save("api_calls.json", calls)

    if note is None:
        _finalize(
            "failed",
            error_code="NOT_FOUND",
            error_message="Note not found.",
            response_summary={"found": False},
        )
        return _err("NOT_FOUND", "Note not found.", id=id, api_call_id=api_call["id"])

    _finalize(
        "succeeded",
        response_summary={"found": True, "note_id": note.get("id"), "xhs_note_id": note.get("xhs_note_id")},
    )

    # Return persisted row as-is (no fabrication)
    return {
        "api_call_id": api_call["id"],
        "note": note,
    }
